import{_ as e,c as r,o as t,an as h}from"./chunks/framework.BWTWahbf.js";const c=JSON.parse('{"title":"世界观","description":"","frontmatter":{},"headers":[],"relativePath":"世界观.md","filePath":"世界观.md"}'),o={name:"世界观.md"};function i(l,a,n,d,_,p){return t(),r("div",null,a[0]||(a[0]=[h('<h1 id="世界观" tabindex="-1">世界观 <a class="header-anchor" href="#世界观" aria-label="Permalink to &quot;世界观&quot;">​</a></h1><h2 id="_2453年" tabindex="-1">2453年 <a class="header-anchor" href="#_2453年" aria-label="Permalink to &quot;2453年&quot;">​</a></h2><p>12月11日，陨石雨袭击云棠河西地区星辰市，撞击点附近出现神秘力量，全国各地断联。随即，云棠组织凌云军前往救援。</p><p>月底，在连夜抢修下，通讯恢复。第一届新纪元全球安全峰会在云棠首都燕京市隆重召开，云棠天机阁天督陆承影发表讲话：“世界人民应当团结一心，共同重建我们的家园。”</p><h2 id="_2454年" tabindex="-1">2454年 <a class="header-anchor" href="#_2454年" aria-label="Permalink to &quot;2454年&quot;">​</a></h2><p>1月，云棠天机阁承诺将在5年内安定1200余万难民，免费提供住房、物资，分配工作。面对世界各界提出的质疑，陆承影表示：“全国1200多万人等着回家，我们没有‘能不能’这个选项，只有‘什么时候’。”</p><p>2月，云棠天机阁宣布成立云棠联合救援局，负责难民安置、物资发放、工作分配等事务。</p><p>3月，星辰难民所及其分所成立</p><p>8月，云棠成立灾后经济特区，实行特殊优惠政策，吸引国内外企业投资。灾后经济特区包括燕京市、龙渊市、客城市、湖中区、蜀山市、清湖市等。</p><h2 id="_2455年" tabindex="-1">2455年 <a class="header-anchor" href="#_2455年" aria-label="Permalink to &quot;2455年&quot;">​</a></h2><p>5月，国际灾难互助联盟成立，云棠等十个国家为初始会员国。伺候几年内，该组织增至100余个会员国。</p><p>8月，互助联盟队伍深入云棠西北部，开始研究神秘地心力量。</p><h2 id="_2458年" tabindex="-1">2458年 <a class="header-anchor" href="#_2458年" aria-label="Permalink to &quot;2458年&quot;">​</a></h2><p>1月29日，最后一批难民到达新城，云棠国5年承诺提前完成，全国1200余万难民已全部安置。这一天被定为“云棠难民安置纪念日”。</p><h2 id="_2455年-2465年" tabindex="-1">2455年-2465年 <a class="header-anchor" href="#_2455年-2465年" aria-label="Permalink to &quot;2455年-2465年&quot;">​</a></h2><p>互助联盟研究成果甚微，损失惨重，研究被迫终止。</p><h2 id="_2466年" tabindex="-1">2466年 <a class="header-anchor" href="#_2466年" aria-label="Permalink to &quot;2466年&quot;">​</a></h2><p>3月11日，地球远征舰队出发寻找新家园。</p><h2 id="_2471年" tabindex="-1">2471年 <a class="header-anchor" href="#_2471年" aria-label="Permalink to &quot;2471年&quot;">​</a></h2><p>1月，互助联盟重整旗鼓，重新上阵研究灾区神秘力量。</p><h2 id="_2473年" tabindex="-1">2473年 <a class="header-anchor" href="#_2473年" aria-label="Permalink to &quot;2473年&quot;">​</a></h2><p>陆承影卸任天机阁天督职位。</p><h2 id="_2479年" tabindex="-1">2479年 <a class="header-anchor" href="#_2479年" aria-label="Permalink to &quot;2479年&quot;">​</a></h2><p>陆承影逝世，云棠全国哀悼。</p><h2 id="_2484年" tabindex="-1">2484年 <a class="header-anchor" href="#_2484年" aria-label="Permalink to &quot;2484年&quot;">​</a></h2><p>7月，地心神秘力量已被基本控制，并被锁在一定的维度中，以保证人们安全。</p><h2 id="_2487年" tabindex="-1">2487年 <a class="header-anchor" href="#_2487年" aria-label="Permalink to &quot;2487年&quot;">​</a></h2><p>10月，探险文化热度持续上升，探险家协会成立。</p><h2 id="_2488年" tabindex="-1">2488年 <a class="header-anchor" href="#_2488年" aria-label="Permalink to &quot;2488年&quot;">​</a></h2><p>2月，星辰简称探险家地下组织中心。</p><h2 id="_2493年" tabindex="-1">2493年 <a class="header-anchor" href="#_2493年" aria-label="Permalink to &quot;2493年&quot;">​</a></h2><p>陆承影的学生秦绍先就职云棠天机阁天督。</p><h2 id="_2504年" tabindex="-1">2504年 <a class="header-anchor" href="#_2504年" aria-label="Permalink to &quot;2504年&quot;">​</a></h2><p>小蕉接管龙渊市，重建荒废事业。</p><h2 id="_2508年" tabindex="-1">2508年 <a class="header-anchor" href="#_2508年" aria-label="Permalink to &quot;2508年&quot;">​</a></h2><p>1月29日，云棠难民安置50周年纪念活动在燕京隆重举行。秦绍先天督发表重要讲话。</p><p>2月1日，地球远征舰队传来讯号，发现新家园。该星系代号为YL-35421，被命名为云琉星系，里面的3颗宜居行星被分别命名为云琉一号、云琉二号、云琉三号。人们决定先探索云琉一号。</p><h2 id="_2512年" tabindex="-1">2512年 <a class="header-anchor" href="#_2512年" aria-label="Permalink to &quot;2512年&quot;">​</a></h2><p>地球与云琉一号建立跃迁门，“开拓时代”正式开始。</p>',39)]))}const u=e(o,[["render",i]]);export{c as __pageData,u as default};
